    @EventHandler( payloadType=CreateObservationEvent.class )
    public void handle( CreateObservationEvent event) {
	    LOGGER.info("handling CreateObservationEvent - " + event );
	    Observation entity = new Observation();
            entity.setObservationId( event.getObservationId() );
            entity.setCode( event.getCode() );
            entity.setValue( event.getValue() );
            entity.setUnit( event.getUnit() );
            entity.setEffectiveDateTime( event.getEffectiveDateTime() );
            entity.setInterpretation( event.getInterpretation() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllObservation( entity );
    }

