    /**
     * Method to retrieve the Observation via an ObservationPrimaryKey.
     * @param 	id Long
     * @return 	Observation
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Observation handle( FindObservationQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getObservationId() );
    }
    
    /**
     * Method to retrieve a collection of all Observations
     *
     * @param	query	FindAllObservationQuery 
     * @return 	List<Observation> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Observation> handle( FindAllObservationQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindObservation,
 * but only if the id matches
 *
 * @param		entity	Observation
 */
	protected void emitFindObservation( Observation entity ) {
		LOGGER.info("handling emitFindObservation" );
		
	    queryUpdateEmitter.emit(FindObservationQuery.class,
	                            query -> query.getFilter().getObservationId().equals(entity.getObservationId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllObservation
	 * 
	 * @param		entity	Observation
	 */
	protected void emitFindAllObservation( Observation entity ) {
		LOGGER.info("handling emitFindAllObservation" );
		
	    queryUpdateEmitter.emit(FindAllObservationQuery.class,
	                            query -> true,
	                            entity);
	}

